package setup

import (
	"database/sql"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strconv"
	"testing"

	"github.com/mickey-kras/gpu-workload-supervisor/internal/control"
	gpuruntime "github.com/mickey-kras/gpu-workload-supervisor/internal/runtime"
)

// These bytes were generated by OwnedProfile at commit 62b4e0e.
func TestHistoricalOwnedOllamaProfilesCanBeRemoved(t *testing.T) {
	for _, count := range []int{1, 2} {
		t.Run(strconv.Itoa(count)+" profiles", func(t *testing.T) {
			b, home, request := fixture(t)
			b.runCommand = fakeOwnedCommandFor(home)
			if err := b.Apply(t.Context(), home, request); err != nil {
				t.Fatal(err)
			}
			snapshot, err := ReadCatalog(t.Context(), request.Profile.StatePath)
			if err != nil {
				t.Fatal(err)
			}
			raw, err := os.ReadFile("../control/testdata/legacy-owned-ollama/catalog.json")
			if err != nil {
				t.Fatal(err)
			}
			catalog, err := control.DecodeStoredCatalog(raw)
			if err != nil {
				t.Fatal(err)
			}
			catalog.Profiles = catalog.Profiles[:count]
			for i := range catalog.Profiles {
				catalog.Profiles[i].NativeModel.LaunchFile = filepath.Join(ownedUnitDirectory(home), catalog.Profiles[i].Unit)
			}
			unit := catalog.Profiles[0].Unit
			content, err := os.ReadFile(filepath.Join("../control/testdata/legacy-owned-ollama", unit))
			if err != nil {
				t.Fatal(err)
			}
			if digest(content) != catalog.Profiles[0].NativeModel.LaunchSHA256 {
				t.Fatal("historical fixture fingerprint differs")
			}
			if err := os.MkdirAll(ownedUnitDirectory(home), 0700); err != nil {
				t.Fatal(err)
			}
			path := filepath.Join(ownedUnitDirectory(home), unit)
			if err := os.WriteFile(path, content, 0600); err != nil {
				t.Fatal(err)
			}
			raw, err = json.Marshal(catalog)
			if err != nil {
				t.Fatal(err)
			}
			db, err := sql.Open("sqlite", request.Profile.StatePath)
			if err != nil {
				t.Fatal(err)
			}
			if _, err := db.Exec("UPDATE workload_catalog SET catalog=?", raw); err != nil {
				t.Fatal(err)
			}
			if _, err := db.Exec("UPDATE workload_catalog_history SET catalog=? WHERE revision=?", raw, snapshot.Revision); err != nil {
				t.Fatal(err)
			}
			db.Close()
			discovery, err := b.Discover(t.Context(), home)
			if err != nil {
				t.Fatal(err)
			}
			if len(discovery.Request.Catalog.Profiles) != count || discovery.Request.ExpectedRevision != snapshot.Revision {
				t.Fatal("historical profiles unavailable")
			}
			if discovery.Request.Catalog.Validate() == nil {
				t.Fatal("removed runtime allowed for execution")
			}
			b.makeRuntime = func(request Request) (gpuruntime.Manager, error) {
				if err := request.Catalog.Validate(); err != nil {
					return nil, err
				}
				return idleRuntime{}, nil
			}
			request.ExpectedRevision = snapshot.Revision
			replacement, _ := ownedFixtureProfile(t, home, "ollama-local", 9100)
			request.Catalog = control.Catalog{Version: 2, Profiles: []control.WorkloadProfile{replacement}}
			if err := b.Apply(t.Context(), home, request); err == nil {
				t.Fatal("historical unit overwritten before removal")
			}
			request.Catalog = control.Catalog{Version: 2, Disabled: true}
			if err := os.WriteFile(path, []byte("changed"), 0600); err != nil {
				t.Fatal(err)
			}
			if err := b.Apply(t.Context(), home, request); !errors.Is(err, ErrOwnedUnitModified) {
				t.Fatal("modified unit removal accepted", err)
			}
			if err := os.WriteFile(path, content, 0600); err != nil {
				t.Fatal(err)
			}
			if err := b.Apply(t.Context(), home, request); err != nil {
				t.Fatal(err)
			}
			after, err := ReadCatalog(t.Context(), request.Profile.StatePath)
			if err != nil || !after.Catalog.Disabled {
				t.Fatal(after, err)
			}
			if _, err := os.Stat(path); !errors.Is(err, os.ErrNotExist) {
				t.Fatal("old shared unit survived", err)
			}
		})
	}
}
